using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class DestructionWorkflowOperations
{
    private static SpinBox Number()=>new DragNumber();
    public void bake_dialog(Control owner,Control view)
    {
        var actor=Actor(owner);var dialog=new ConfirmationDialog{Name="DestructionBakeDialog",Title="Bake interacting simulation",OkButtonText="Bake",DialogHideOnOk=false};owner.AddChild(dialog);var fields=new VBoxContainer();dialog.AddChild(fields);fields.AddChild(new Label{Text="All configured physics actors are baked together."});var external=new CheckButton{Name="ExternalBakeStorage",Text="Stream chunks to project (bounded memory)"};fields.AddChild(external);var bake=_settings.authored(actor)["bake"].AsGodotDictionary();var interval=new CheckButton{Name="RecalculateBakeInterval",Text="Reuse verified prefix; recalculate from playhead",Disabled=!ActorDataOperations.ScriptIs(Get(bake,"cache").AsGodotObject() as Resource,"res://scripts/actors/physics/destruction/physics_bake_cache.gd")};fields.AddChild(interval);var inputs=new SpinBox[3];var titles=new[]{"Start (scene seconds)","End (scene seconds)","Samples per second"};var defaults=new[]{0.0,view.Get("video_duration").AsDouble(),view.Get("physics").AsGodotObject().Get("rate").AsDouble()};for(int i=0;i<3;i++){var row=new HBoxContainer();fields.AddChild(row);row.AddChild(new Label{Text=titles[i],SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});var input=Number();input.Name=titles[i].ValidateNodeName();input.MinValue=0;input.MaxValue=i==2?240:86400;input.Step=i==2?1:.01;input.SetValueNoSignal(defaults[i]);row.AddChild(input);inputs[i]=input;}interval.Toggled+=enabled=>{if(!enabled)return;var bake=_settings.authored(actor)["bake"].AsGodotDictionary();inputs[0].Value=Get(bake,"from",0).AsDouble();inputs[1].Value=Get(bake,"to",view.Get("video_duration")).AsDouble();inputs[2].Value=Get(bake,"rate",view.Get("physics").AsGodotObject().Get("rate")).AsDouble();};var progress=new ProgressBar{ShowPercentage=true};fields.AddChild(progress);var info=new Label{AutowrapMode=TextServer.AutowrapMode.WordSmart};fields.AddChild(info);var job=new Settings{["running"]=false,["dialog"]=dialog,["info"]=info,["feedback"]=owner.Get("status"),["progress"]=progress};var callback=Callable.From<long,long,long>((done,total,bytes)=>{if(!GodotObject.IsInstanceValid(progress))return;progress.Value=100.0*done/total;info.Text=done+" / "+total+" samples · "+(bytes/1048576.0).ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+" MiB compressed";});dialog.Confirmed+=()=>{if(job["running"].AsBool())return;job["running"]=true;dialog.GetOkButton().Disabled=true;var options=new Settings{["external"]=external.ButtonPressed};if(interval.ButtonPressed){options["reuse"]=_settings.authored(actor)["bake"];options["recalculate_from"]=view.Get("canvas").AsGodotObject().Get("playhead");}owner.Call("_await_group_bake",view,inputs[0].Value,inputs[1].Value,(int)inputs[2].Value,callback,options,job);};dialog.Canceled+=()=>{if(job["running"].AsBool())view.Get("physics").AsGodotObject().Call("cancel_bake");else dialog.QueueFree();};dialog.TreeExiting+=()=>{if(job["running"].AsBool()&&GodotObject.IsInstanceValid(view))view.Get("physics").AsGodotObject().Call("cancel_bake");};dialog.PopupCentered(new Vector2I(430,260));
    }
    public void group_bake_finished(Settings job,string error){var dialog=job["dialog"].AsGodotObject() as ConfirmationDialog;if(GodotObject.IsInstanceValid(dialog)){job["running"]=false;dialog!.GetOkButton().Disabled=false;var info=job["info"].AsGodotObject() as Label;if(GodotObject.IsInstanceValid(info))info!.Text=error.Length>0?error:"Bake saved. Source settings and correction keys remain editable.";}var feedback=job["feedback"].AsGodotObject() as Label;if(GodotObject.IsInstanceValid(feedback))feedback!.Text=error.Length>0?error:"Interacting group baked.";}
}
